// Shared shopping list: HTTP API + polling web UI, durable in SQLite.
package main

import (
	"database/sql"
	"encoding/json"
	"log"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"

	_ "github.com/mattn/go-sqlite3"
)

type Item struct {
	ID      int64  `json:"id"`
	Text    string `json:"text"`
	Bought  bool   `json:"bought"`
	Created string `json:"created"`
	Updated string `json:"updated"`
}

var (
	db     *sql.DB
	mu     sync.Mutex
	seq    int64
)

func now() string { return time.Now().UTC().Format(time.RFC3339Nano) }

func bump() { mu.Lock(); seq++; mu.Unlock() }

func openDB(path string) error {
	var err error
	db, err = sql.Open("sqlite3", path+"?_busy_timeout=5000&_journal_mode=WAL&_foreign_keys=on")
	if err != nil {
		return err
	}
	db.SetMaxOpenConns(1)
	_, err = db.Exec(`CREATE TABLE IF NOT EXISTS items (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		text TEXT NOT NULL,
		bought INTEGER NOT NULL DEFAULT 0,
		created TEXT NOT NULL,
		updated TEXT NOT NULL
	)`)
	return err
}

func listItems() ([]Item, error) {
	rows, err := db.Query(`SELECT id, text, bought, created, updated FROM items ORDER BY id`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []Item{}
	for rows.Next() {
		var it Item
		var b int
		if err := rows.Scan(&it.ID, &it.Text, &b, &it.Created, &it.Updated); err != nil {
			return nil, err
		}
		it.Bought = b != 0
		out = append(out, it)
	}
	return out, rows.Err()
}

func writeJSON(w http.ResponseWriter, code int, v interface{}) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	w.WriteHeader(code)
	json.NewEncoder(w).Encode(v)
}

func readItemBody(r *http.Request) (text string, bought *bool, err error) {
	var body struct {
		Text   *string `json:"text"`
		Item   *string `json:"item"`
		Bought *bool   `json:"bought"`
	}
	dec := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
	if err := dec.Decode(&body); err != nil {
		return "", nil, err
	}
	if body.Text != nil {
		text = *body.Text
	} else if body.Item != nil {
		text = *body.Item
	}
	return strings.TrimSpace(text), body.Bought, nil
}

func apiItems(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		items, err := listItems()
		if err != nil {
			writeJSON(w, 500, map[string]string{"error": err.Error()})
			return
		}
		writeJSON(w, 200, map[string]interface{}{"items": items, "seq": seq, "now": now()})
	case http.MethodPost:
		text, _, err := readItemBody(r)
		if err != nil {
			writeJSON(w, 400, map[string]string{"error": "bad json"})
			return
		}
		if text == "" {
			writeJSON(w, 400, map[string]string{"error": "text required"})
			return
		}
		if len(text) > 500 {
			text = text[:500]
		}
		t := now()
		res, err := db.Exec(`INSERT INTO items (text, bought, created, updated) VALUES (?, 0, ?, ?)`, text, t, t)
		if err != nil {
			writeJSON(w, 500, map[string]string{"error": err.Error()})
			return
		}
		id, _ := res.LastInsertId()
		bump()
		writeJSON(w, 201, Item{ID: id, Text: text, Bought: false, Created: t, Updated: t})
	default:
		w.Header().Set("Allow", "GET, POST")
		writeJSON(w, 405, map[string]string{"error": "method not allowed"})
	}
}

func apiItem(w http.ResponseWriter, r *http.Request) {
	rest := strings.TrimPrefix(r.URL.Path, "/api/items/")
	parts := strings.Split(strings.Trim(rest, "/"), "/")
	id, err := strconv.ParseInt(parts[0], 10, 64)
	if err != nil {
		writeJSON(w, 400, map[string]string{"error": "bad id"})
		return
	}
	switch {
	case r.Method == http.MethodDelete && len(parts) == 1:
		res, err := db.Exec(`DELETE FROM items WHERE id = ?`, id)
		if err != nil {
			writeJSON(w, 500, map[string]string{"error": err.Error()})
			return
		}
		n, _ := res.RowsAffected()
		if n == 0 {
			writeJSON(w, 404, map[string]string{"error": "not found"})
			return
		}
		bump()
		writeJSON(w, 200, map[string]interface{}{"deleted": id})
	case r.Method == http.MethodPost && len(parts) == 2 && parts[1] == "toggle":
		var it Item
		var b int
		err := db.QueryRow(`SELECT id, text, bought, created, updated FROM items WHERE id = ?`, id).
			Scan(&it.ID, &it.Text, &b, &it.Created, &it.Updated)
		if err == sql.ErrNoRows {
			writeJSON(w, 404, map[string]string{"error": "not found"})
			return
		} else if err != nil {
			writeJSON(w, 500, map[string]string{"error": err.Error()})
			return
		}
		nb := 0
		if b == 0 {
			nb = 1
		}
		t := now()
		if _, err := db.Exec(`UPDATE items SET bought = ?, updated = ? WHERE id = ?`, nb, t, id); err != nil {
			writeJSON(w, 500, map[string]string{"error": err.Error()})
			return
		}
		bump()
		it.Bought = nb == 1
		it.Updated = t
		writeJSON(w, 200, it)
	case (r.Method == http.MethodPatch || r.Method == http.MethodPut) && len(parts) == 1:
		text, bought, err := readItemBody(r)
		if err != nil {
			writeJSON(w, 400, map[string]string{"error": "bad json"})
			return
		}
		var it Item
		var b int
		err = db.QueryRow(`SELECT id, text, bought, created, updated FROM items WHERE id = ?`, id).
			Scan(&it.ID, &it.Text, &b, &it.Created, &it.Updated)
		if err == sql.ErrNoRows {
			writeJSON(w, 404, map[string]string{"error": "not found"})
			return
		} else if err != nil {
			writeJSON(w, 500, map[string]string{"error": err.Error()})
			return
		}
		newText := it.Text
		if text != "" {
			newText = text
		}
		if len(newText) > 500 {
			newText = newText[:500]
		}
		nb := b
		if bought != nil {
			if *bought {
				nb = 1
			} else {
				nb = 0
			}
		}
		t := now()
		if _, err := db.Exec(`UPDATE items SET text = ?, bought = ?, updated = ? WHERE id = ?`, newText, nb, t, id); err != nil {
			writeJSON(w, 500, map[string]string{"error": err.Error()})
			return
		}
		bump()
		it.Text, it.Bought, it.Updated = newText, nb == 1, t
		writeJSON(w, 200, it)
	case r.Method == http.MethodGet && len(parts) == 1:
		items, err := listItems()
		if err != nil {
			writeJSON(w, 500, map[string]string{"error": err.Error()})
			return
		}
		for _, it := range items {
			if it.ID == id {
				writeJSON(w, 200, it)
				return
			}
		}
		writeJSON(w, 404, map[string]string{"error": "not found"})
	default:
		writeJSON(w, 405, map[string]string{"error": "method not allowed"})
	}
}

func index(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" && r.URL.Path != "/index.html" {
		http.NotFound(w, r)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	w.Write([]byte(page))
}

func main() {
	addr := os.Getenv("ADDR")
	if addr == "" {
		addr = ":8080"
	}
	dbPath := os.Getenv("DB_PATH")
	if dbPath == "" {
		dbPath = "/data/shop.db"
	}
	if err := openDB(dbPath); err != nil {
		log.Fatalf("open db %s: %v", dbPath, err)
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/api/items", apiItems)
	mux.HandleFunc("/api/items/", apiItem)
	mux.HandleFunc("/api/health", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, 200, map[string]string{"status": "ok"})
	})
	mux.HandleFunc("/", index)
	srv := &http.Server{Addr: addr, Handler: mux, ReadHeaderTimeout: 10 * time.Second}
	log.Printf("shopping list listening on %s, db %s", addr, dbPath)
	log.Fatal(srv.ListenAndServe())
}
