<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Shopping list</title>
<style>
  :root { color-scheme: light dark; }
  body { font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; max-width: 34rem;
         margin: 2rem auto; padding: 0 1rem; }
  h1 { font-size: 1.5rem; margin-bottom: 1rem; }
  form { display: flex; gap: .5rem; margin-bottom: 1rem; }
  label { display: block; font-weight: 600; margin-bottom: .35rem; }
  input[type=text] { flex: 1; padding: .55rem .65rem; font-size: 1rem; border: 1px solid #888;
                     border-radius: .4rem; }
  button { padding: .55rem 1rem; font-size: 1rem; border-radius: .4rem; border: 1px solid #3b6ea5;
           background: #3b6ea5; color: #fff; cursor: pointer; }
  button:disabled { opacity: .6; cursor: default; }
  ul { list-style: none; padding: 0; margin: 0; }
  li { display: flex; align-items: center; gap: .6rem; padding: .5rem .25rem;
       border-bottom: 1px solid rgba(128,128,128,.3); }
  li label.item { font-weight: normal; margin: 0; flex: 1; cursor: pointer; }
  li input[type=checkbox] { width: 1.15rem; height: 1.15rem; cursor: pointer; }
  li.bought label.item { text-decoration: line-through; opacity: .6; }
  .empty { opacity: .6; padding: .75rem .25rem; }
  .status { font-size: .8rem; opacity: .6; margin-top: 1rem; }
</style>
</head>
<body>
<h1>Shopping list</h1>
<div>
  <label for="item">Item</label>
  <form id="add-form">
    <input type="text" id="item" name="item" placeholder="e.g. milk" autocomplete="off" maxlength="500" required>
    <button type="submit" id="add-btn">Add</button>
  </form>
</div>
<ul id="list"></ul>
<div class="empty" id="empty" hidden>No items yet.</div>
<div class="status" id="status">&nbsp;</div>
<script>
(function () {
  var listEl = document.getElementById('list');
  var emptyEl = document.getElementById('empty');
  var statusEl = document.getElementById('status');
  var input = document.getElementById('item');
  var form = document.getElementById('add-form');
  var known = {};        // id -> signature of last rendered state
  var pending = {};      // ids with a local change in flight
  var pollMs = 1000;
  var lastOk = null;

  function setStatus(t) { statusEl.textContent = t; }

  function render(items) {
    var seen = {};
    items.forEach(function (it) { seen[it.id] = true; });
    Array.prototype.slice.call(listEl.children).forEach(function (li) {
      if (!seen[li.dataset.id]) { delete known[li.dataset.id]; li.remove(); }
    });
    items.forEach(function (it, idx) {
      var sig = it.text + '|' + it.bought;
      if (known[it.id] === sig) {
        var existing = listEl.querySelector('li[data-id="' + it.id + '"]');
        if (existing && listEl.children[idx] !== existing) listEl.insertBefore(existing, listEl.children[idx] || null);
        return;
      }
      var li = listEl.querySelector('li[data-id="' + it.id + '"]');
      if (!li) {
        li = document.createElement('li');
        li.dataset.id = it.id;
        var cb = document.createElement('input');
        cb.type = 'checkbox';
        var cbid = 'cb-' + it.id;
        cb.id = cbid;
        var lab = document.createElement('label');
        lab.className = 'item';
        lab.htmlFor = cbid;
        cb.addEventListener('change', function () { toggle(it.id, cb); });
        li.appendChild(cb);
        li.appendChild(lab);
        listEl.appendChild(li);
      }
      li.classList.toggle('bought', !!it.bought);
      li.querySelector('input[type=checkbox]').checked = !!it.bought;
      li.querySelector('label.item').textContent = it.text;
      listEl.insertBefore(li, listEl.children[idx] || null);
      known[it.id] = sig;
    });
    emptyEl.hidden = items.length > 0;
  }

  function poll() {
    fetch('/api/items', { cache: 'no-store', headers: { 'Accept': 'application/json' } })
      .then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
      .then(function (data) {
        render(data.items || []);
        lastOk = new Date();
        setStatus('Synced ' + lastOk.toLocaleTimeString());
      })
      .catch(function (e) { setStatus('Offline, retrying… (' + e.message + ')'); })
      .then(function () { setTimeout(poll, pollMs); });
  }

  function toggle(id, cb) {
    var want = cb.checked;
    pending[id] = true;
    fetch('/api/items/' + id, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ bought: want })
    }).then(function (r) { return r.json(); })
      .then(function (it) { known[id] = it.text + '|' + it.bought; })
      .catch(function () { cb.checked = !want; })
      .then(function () { delete pending[id]; pollOnce(); });
  }

  function pollOnce() {
    fetch('/api/items', { cache: 'no-store' })
      .then(function (r) { return r.json(); })
      .then(function (data) { render(data.items || []); })
      .catch(function () {});
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var text = input.value.trim();
    if (!text) return;
    var btn = document.getElementById('add-btn');
    btn.disabled = true;
    fetch('/api/items', {
      method: 'POST',
